import{I as o,c as l,o as r,a8 as s,J as i,a9 as n,aa as c,ab as _,ac as p}from"./chunks/framework.jsZJWZJf.js";const b=JSON.parse('{"title":"《许三观卖血记》有感","description":"","frontmatter":{},"headers":[],"relativePath":"blog/read/读后感/20210409许三观卖血记.md","filePath":"blog/read/读后感/20210409许三观卖血记.md","lastUpdated":1795103431000}'),d={name:"blog/read/读后感/20210409许三观卖血记.md"},u=Object.assign(d,{setup(h){const e=[{src:n,alt:"桌上的泡鸡爪、红糖冰粉和火龙果",caption:"泡鸡爪、红糖冰粉和火龙果"},{src:c,alt:"蓝色便签上写着「冰箱有酸奶哟」",caption:"妈妈留的小纸条"},{src:_,alt:"葡萄",caption:"买的葡萄让在火车上吃"},{src:p,alt:"延边牛肉",caption:"延边牛肉"}];return(m,a)=>{const t=o("PhotoGallery");return r(),l("div",null,[a[0]||(a[0]=s('<h1 id="《许三观卖血记》有感" tabindex="-1">《许三观卖血记》有感 <a class="header-anchor" href="#《许三观卖血记》有感" aria-label="Permalink to “《许三观卖血记》有感”">​</a></h1><h2 id="_2021-04-09-08-57-周五" tabindex="-1">2021-04-09 08:57 周五 <a class="header-anchor" href="#_2021-04-09-08-57-周五" aria-label="Permalink to “2021-04-09 08:57 周五”">​</a></h2><ul><li><p>最近看了许三观卖血记这本书，是一个小人物悲伤的故事，是一个关于父爱母爱的感人故事。许三观是一个小人物，养了一个不是自己亲儿子的孩子一辈子，为了他卖了好几次血，差点把自己的命都卖掉，就只是为了自己的孩子，为了赚一些治病的医疗费。最后他妻子许玉兰说的那些话最叫人感动：你爸爸是在用血养你们！</p></li><li><p>其实我们也一样，虽然父母没有像许三观那样靠卖血才能养活我们，但是他们一辈子耗费在我们身上的精力有何不是他们的血呢！最后许三观知道自己的血没人要了之后的反应更是让人心疼，那是一种老了之后，不被人需要的感觉，仿佛自己剩余的价值都没有了，会被全世界抛弃的感觉。不在需要许三观卖血才能养活这个家，靠卖血养活了整个家的许三观，可能世界都崩塌了，到最后他都还在想，他的血卖不出去，家里面再遇到危险怎么办？就再也没有人能帮他，帮这个家遮风挡雨了。</p></li><li><p>卖血很荒诞，但是为了一个家付出的心却是实时发生在生活里面的。许玉兰也是一个好妻子，陪他一起度过生活中的磕磕绊绊。尤其是文革，许玉兰被批斗的时候，许三观也并没有像其他人那样对她。也是在文革中的一点点温情了。小人物的一生可不就是这样，既有悲哀，也有温暖感人的地方。</p></li><li><p>清明我回家的时候，也是这样的。我妈妈会给我写小纸条，告诉我冰箱里面有酸奶。其实不用她写，我自己去看冰箱的时候也能看到找到。第二天晚上买了泡鸡爪跟红糖冰粉给我吃，还附带一个大火龙果，说是给我的零食。那会心里就很感动，我随便说的什么话，我妈妈都记在心里，还说要给我烤烧烤，怕我在家等太久就没烤，心里面真的很暖。父母给我们的已经很多了！我也希望在他们还没老之前，带他们去更多的地方玩，一定要做到！</p></li></ul>',3)),i(t,{images:e,ratio:"4 / 3",fit:"cover"})])}}});export{b as __pageData,u as default};
